package com.campus.lostfound.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDateTime;
@Entity @Table(name="claims") public class Claim { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Item item; @ManyToOne(optional=false) private User claimant; @NotBlank @Size(max=1500) @Column(nullable=false,length=1500) private String proof; @Enumerated(EnumType.STRING) @Column(nullable=false) private ClaimStatus status=ClaimStatus.PENDING; private LocalDateTime createdAt=LocalDateTime.now(); protected Claim(){} public Claim(Item i,User u,String p){item=i;claimant=u;proof=p;} public Long getId(){return id;} public Item getItem(){return item;} public User getClaimant(){return claimant;} public String getProof(){return proof;} public ClaimStatus getStatus(){return status;} public void setStatus(ClaimStatus s){status=s;} public LocalDateTime getCreatedAt(){return createdAt;} }
